PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE `readings` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`user_id` text NOT NULL,
	`read_at` text NOT NULL,
	`hrc` real NOT NULL,
	`krd` real NOT NULL,
	`boiler_temp` real,
	`outside_temp` real,
	`boiler_status` text DEFAULT 'on' NOT NULL,
	`unit_price` real DEFAULT 0 NOT NULL,
	`note` text DEFAULT '' NOT NULL,
	`created_at` text NOT NULL
, `unit_price_tier2` real DEFAULT 0 NOT NULL);
CREATE TABLE `tariffs` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`user_id` text NOT NULL,
	`effective_from` text NOT NULL,
	`price_per_m3` real NOT NULL,
	`label` text DEFAULT '' NOT NULL,
	`created_at` text NOT NULL
, `price_tier2` real DEFAULT 0 NOT NULL);
CREATE TABLE `boiler_sessions` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`user_id` text NOT NULL,
	`started_at` text NOT NULL,
	`ended_at` text,
	`start_hrc` real NOT NULL,
	`start_krd` real NOT NULL,
	`end_hrc` real,
	`end_krd` real,
	`target_temp` real,
	`outside_temp` real,
	`note` text DEFAULT '' NOT NULL,
	`created_at` text NOT NULL
);
CREATE TABLE IF NOT EXISTS "settings" (
	`user_id` text PRIMARY KEY NOT NULL,
	`building_name` text DEFAULT 'Apartmanımız' NOT NULL,
	`apartment_count` integer DEFAULT 20 NOT NULL,
	`krd_alert` real DEFAULT 300 NOT NULL,
	`city` text DEFAULT 'Eti Mahallesi, Çankaya / Ankara' NOT NULL,
	`updated_at` text NOT NULL
);
CREATE TABLE limit_versions (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, user_id text NOT NULL, effective_from text NOT NULL, year integer NOT NULL, month integer NOT NULL, per_home_limit real NOT NULL, source_label text DEFAULT '' NOT NULL, source_url text DEFAULT '' NOT NULL, note text DEFAULT '' NOT NULL, created_at text NOT NULL);
DELETE FROM sqlite_sequence;
CREATE INDEX `readings_user_date_idx` ON `readings` (`user_id`,`read_at`);
CREATE UNIQUE INDEX `readings_user_exact_date_idx` ON `readings` (`user_id`,`read_at`);
CREATE INDEX `tariffs_user_date_idx` ON `tariffs` (`user_id`,`effective_from`);
CREATE UNIQUE INDEX `tariffs_user_exact_date_idx` ON `tariffs` (`user_id`,`effective_from`);
CREATE INDEX `boiler_sessions_user_start_idx` ON `boiler_sessions` (`user_id`,`started_at`);
CREATE INDEX limit_versions_user_month_idx ON limit_versions (user_id,year,month,effective_from);
CREATE UNIQUE INDEX limit_versions_user_exact_idx ON limit_versions (user_id,effective_from,year,month);
